   176→// ==================== 린터 ====================
   177→
   178→class Diagnostic {
   179→  final int line;
   180→  final int column;
   181→  final String message;
   182→  final DiagnosticSeverity severity;
   183→  final String code;
   184→
   185→  Diagnostic({
   186→    required this.line,
   187→    required this.column,
   188→    required this.message,
   189→    required this.severity,
   190→    required this.code,
   191→  });
   192→}
   193→
   194→enum DiagnosticSeverity {
   195→  error,
   196→  warning,
   197→  information,
   198→  hint,
   199→}
   200→
   201→class Linter {
   202→  /// 코드 린팅 및 문제점 감지
   203→  static List<Diagnostic> lint(String code) {
   204→    final diagnostics = <Diagnostic>[];
   205→    final lines = code.split('\n');
   206→
   207→    for (int lineNum = 0; lineNum < lines.length; lineNum++) {
   208→      final line = lines[lineNum];
   209→
   210→      // 1. 구문 오류 감지
   211→      final syntaxErrors = _checkSyntaxErrors(line, lineNum);
   212→      diagnostics.addAll(syntaxErrors);
   213→
   214→      // 2. 미사용 변수 감지
   215→      final unusedVars = _checkUnusedVariables(code, lineNum);
   216→      diagnostics.addAll(unusedVars);
   217→
   218→      // 3. 타입 불일치 감지
   219→      final typeErrors = _checkTypeErrors(line, lineNum);
   220→      diagnostics.addAll(typeErrors);
   221→
   222→      // 4. 스타일 경고 감지
   223→      final styleWarnings = _checkStyleWarnings(line, lineNum);
   224→      diagnostics.addAll(styleWarnings);
   225→    }
   226→
   227→    return diagnostics;
   228→  }
   229→
   230→  static List<Diagnostic> _checkSyntaxErrors(String line, int lineNum) {
   231→    final diagnostics = <Diagnostic>[];
   232→
   233→    // 괄호 짝맞음 확인
   234→    int openParen = 0, openBrace = 0, openBracket = 0;
   235→    for (int i = 0; i < line.length; i++) {
   236→      final char = line[i];
   237→      if (char == '(') openParen++;
   238→      else if (char == ')') openParen--;
   239→      else if (char == '{') openBrace++;
   240→      else if (char == '}') openBrace--;
   241→      else if (char == '[') openBracket++;
   242→      else if (char == ']') openBracket--;
   243→
   244→      if (openParen < 0 || openBrace < 0 || openBracket < 0) {
   245→        diagnostics.add(Diagnostic(
   246→          line: lineNum,
   247→          column: i,
   248→          message: 'Mismatched closing bracket',
   249→          severity: DiagnosticSeverity.error,
   250→          code: 'syntax-error',
   251→        ));
   252→        break;
   253→      }
   254→    }
   255→
   256→    // 문장 끝 세미콜론 확인 (선택사항이지만 권장)
   257→    if (line.trim().isNotEmpty &&
   258→        !line.trim().endsWith('{') &&
   259→        !line.trim().endsWith('}') &&
   260→        !line.trim().endsWith(';')) {
   261→      // 세미콜론 없음 경고 (힌트)
   262→    }
   263→
   264→    return diagnostics;
   265→  }
   266→
   267→  static List<Diagnostic> _checkUnusedVariables(String code, int lineNum) {
   268→    final diagnostics = <Diagnostic>[];
   269→
   270→    // 간단한 패턴 매칭: let x = ... 근데 x를 사용하지 않음
   271→    final letPattern = RegExp(r'let\s+(\w+)\s*=');
   272→    final lines = code.split('\n');
   273→
   274→    for (int i = 0; i < lines.length; i++) {
   275→      final match = letPattern.firstMatch(lines[i]);
   276→      if (match != null) {
   277→        final varName = match.group(1)!;
   278→        // 이후 줄에서 varName이 사용되는지 확인
   279→        bool isUsed = false;
   280→        for (int j = i + 1; j < lines.length; j++) {
   281→          if (lines[j].contains(varName)) {
   282→            isUsed = true;
   283→            break;
   284→          }
   285→        }
   286→
   287→        if (!isUsed && i == lineNum) {
   288→          diagnostics.add(Diagnostic(
   289→            line: i,
   290→            column: match.start,
   291→            message: "Variable '$varName' is defined but never used",
   292→            severity: DiagnosticSeverity.warning,
   293→            code: 'unused-variable',
   294→          ));
   295→        }
   296→      }
   297→    }
   298→
   299→    return diagnostics;
   300→  }
   301→
   302→  static List<Diagnostic> _checkTypeErrors(String line, int lineNum) {
   303→    final diagnostics = <Diagnostic>[];
   304→
   305→    // 간단한 타입 체크: string + number 같은 명백한 오류
   306→    if (line.contains('+') && line.contains('"')) {
   307→      // 더 정교한 타입 분석은 파서 필요
   308→      // 여기서는 기본적인 패턴만 감지
   309→    }
   310→
   311→    return diagnostics;
   312→  }
   313→
   314→  static List<Diagnostic> _checkStyleWarnings(String line, int lineNum) {
   315→    final diagnostics = <Diagnostic>[];
   316→
   317→    // 들여쓰기 확인 (2칸 또는 4칸 권장)
   318→    final leadingSpaces = line.length - line.trimLeft().length;
   319→    if (leadingSpaces % 2 != 0 && leadingSpaces % 4 != 0 && leadingSpaces > 0) {
   320→      diagnostics.add(Diagnostic(
   321→        line: lineNum,
   322→        column: 0,
   323→        message: 'Incorrect indentation (use 2 or 4 spaces)',
   324→        severity: DiagnosticSeverity.information,
   325→        code: 'indentation',
   326→      ));
   327→    }
   328→
   329→    // 사용하지 않은 import 감지
   330→    if (line.contains('import') && !line.contains('use')) {
   331→      // import 후 실제 사용 여부 확인
   332→    }
   333→
   334→    // 변수명 컨벤션 (camelCase 권장)
   335→    final varPattern = RegExp(r'let\s+([a-z]+_[a-z]+)');
   336→    final match = varPattern.firstMatch(line);
   337→    if (match != null) {
   338→      diagnostics.add(Diagnostic(
   339→        line: lineNum,
   340→        column: match.start,
   341→        message: 'Variable name should use camelCase',
   342→        severity: DiagnosticSeverity.hint,
   343→        code: 'naming-convention',
   344→      ));
   345→    }
   346→
   347→    return diagnostics;
   348→  }
   349→}
   350→
   351→// ==================== 코드 포맷팅 ====================
   352→
   353→class CodeFormatter {
   354→  /// 코드를 표준 형식으로 포맷팅
   355→  static String format(String code) {
   356→    var formatted = code;
   357→
   358→    // 1. 들여쓰기 정규화 (2칸)
   359→    formatted = _normalizeIndentation(formatted);
   360→
   361→    // 2. 공백 정리
   362→    formatted = _cleanupWhitespace(formatted);
   363→
   364→    // 3. 줄 길이 제한 (80자)
   365→    formatted = _wrapLongLines(formatted, maxLength: 80);
   366→
   367→    // 4. 연산자 주변 공백
   368→    formatted = _formatOperators(formatted);
   369→
   370→    return formatted;
   371→  }
   372→
   373→  static String _normalizeIndentation(String code) {
   374→    final lines = code.split('\n');
   375→    final formatted = <String>[];
   376→    int indentLevel = 0;
   377→    const indentStr = '  '; // 2칸
   378→
   379→    for (final line in lines) {
   380→      final trimmed = line.trim();
   381→      if (trimmed.isEmpty) {
   382→        formatted.add('');
   383→        continue;
   384→      }
   385→
   386→      // 닫는 괄호는 들여쓰기 감소
   387→      if (trimmed.startsWith('}') || trimmed.startsWith(']') || trimmed.startsWith(')')) {
   388→        indentLevel = (indentLevel - 1).clamp(0, 100);
   389→      }
   390→
   391→      formatted.add('${'  ' * indentLevel}$trimmed');
   392→
   393→      // 여는 괄호는 들여쓰기 증가
   394→      if (trimmed.endsWith('{') || trimmed.endsWith('[') || trimmed.endsWith('(')) {
   395→        indentLevel++;
   396→      }
   397→    }
   398→
   399→    return formatted.join('\n');
   400→  }
   401→
   402→  static String _cleanupWhitespace(String code) {
   403→    // 라인 끝 공백 제거
   404→    var cleaned = code.split('\n').map((line) => line.trimRight()).join('\n');
   405→
   406→    // 연속된 빈 줄을 최대 1개로
   407→    cleaned = cleaned.replaceAll(RegExp(r'\n\n\n+'), '\n\n');
   408→
   409→    // 파일 끝 개행 확인
   410→    if (!cleaned.endsWith('\n')) {
   411→      cleaned += '\n';
   412→    }
   413→
   414→    return cleaned;
   415→  }
   416→
   417→  static String _wrapLongLines(String code, {int maxLength = 80}) {
   418→    final lines = code.split('\n');
   419→    final wrapped = <String>[];
   420→
   421→    for (final line in lines) {
   422→      if (line.length <= maxLength) {
   423→        wrapped.add(line);
   424→      } else {
   425→        // 길 줄 분할 (공백 기준)
   426→        final parts = line.split(' ');
   427→        var currentLine = '';
   428→        for (final part in parts) {
   429→          if ((currentLine + part).length > maxLength) {
   430→            if (currentLine.isNotEmpty) {
   431→              wrapped.add(currentLine);
   432→              currentLine = '';
   433→            }
   434→            currentLine = part;
   435→          } else {
   436→            if (currentLine.isNotEmpty) {
   437→              currentLine += ' ';
   438→            }
   439→            currentLine += part;
   440→          }
   441→        }
   442→        if (currentLine.isNotEmpty) {
   443→          wrapped.add(currentLine);
   444→        }
   445→      }
   446→    }
   447→
   448→    return wrapped.join('\n');
   449→  }
   450→
   451→  static String _formatOperators(String code) {
   452→    var formatted = code;
   453→
   454→    // 연산자 주변에 공백 추가
   455→    formatted = formatted.replaceAll(RegExp(r'(\S)([+\-*/%=])(\S)'), r'$1 $2 $3');
   456→
   457→    // 콤마 뒤에 공백
   458→    formatted = formatted.replaceAll(RegExp(r',(\S)'), ', $1');
   459→
   460→    return formatted;
   461→  }
   462→}
