     1→// lsp_client.dart - FreeLang LSP (Language Server Protocol) 클라이언트 (중급)
     2→// 기능: 실시간 오류 검증, 자동완성, 심볼 찾기
     3→
     4→import 'dart:async';
     5→
     6→class CompletionItem {
     7→  final String label;
     8→  final int kind; // 1=keyword, 2=function, 3=variable, 4=type
     9→  final String detail;
    10→  final String? insertText;
    11→
    12→  CompletionItem({
    13→    required this.label,
    14→    required this.kind,
    15→    required this.detail,
    16→    this.insertText,
    17→  });
    18→
    19→  factory CompletionItem.fromJson(Map<String, dynamic> json) {
    20→    return CompletionItem(
    21→      label: json['label'] as String? ?? '',
    22→      kind: json['kind'] as int? ?? 0,
    23→      detail: json['detail'] as String? ?? '',
    24→      insertText: json['insertText'] as String?,
    25→    );
    26→  }
    27→
    28→  String get kindName {
    29→    const names = ['', 'keyword', 'function', 'variable', 'type'];
    30→    return names.length > kind ? names[kind] : 'unknown';
    31→  }
    32→}
    33→
    34→class DiagnosticItem {
    35→  final int line;
    36→  final int startCol;
    37→  final int endCol;
    38→  final String message;
    39→  final int severity; // 1=error, 2=warning, 3=info
    40→  final String? code;
    41→
    42→  DiagnosticItem({
    43→    required this.line,
    44→    required this.startCol,
    45→    required this.endCol,
    46→    required this.message,
    47→    required this.severity,
    48→    this.code,
    49→  });
    50→
    51→  factory DiagnosticItem.fromJson(Map<String, dynamic> json) {
    52→    return DiagnosticItem(
    53→      line: json['line'] as int? ?? 0,
    54→      startCol: json['start_col'] as int? ?? 0,
    55→      endCol: json['end_col'] as int? ?? 0,
    56→      message: json['message'] as String? ?? '',
    57→      severity: json['severity'] as int? ?? 3,
    58→      code: json['code'] as String?,
    59→    );
    60→  }
    61→
    62→  bool get isError => severity == 1;
    63→  bool get isWarning => severity == 2;
    64→  bool get isInfo => severity == 3;
    65→}
    66→
    67→class HoverInfo {
