     1→// snippet_uploader.dart - 스니펫 업로더
     2→// IDE에서 작성한 코드를 Hub에 업로드
     3→
     4→import 'package:dio/dio.dart';
     5→
     6→class SnippetUploadResponse {
     7→  final bool success;
     8→  final String snippetId;
     9→  final String shareUrl;
    10→
    11→  SnippetUploadResponse({
    12→    required this.success,
    13→    required this.snippetId,
    14→    required this.shareUrl,
    15→  });
    16→
    17→  factory SnippetUploadResponse.fromJson(Map<String, dynamic> json) {
    18→    return SnippetUploadResponse(
    19→      success: json['success'] as bool? ?? false,
    20→      snippetId: json['data']?['id'] as String? ?? '',
    21→      shareUrl: 'hub://snippet/${json['data']?['id'] ?? ''}',
    22→    );
    23→  }
    24→}
    25→
    26→class SnippetUploader {
    27→  static const String _baseUrl = 'http://localhost:3000/api/v2';
    28→  late Dio _dio;
    29→  bool _initialized = false;
    30→
    31→  SnippetUploader();
    32→
    33→  Future<void> initialize() async {
    34→    if (_initialized) return;
    35→
    36→    _dio = Dio(
    37→      BaseOptions(
    38→        baseUrl: _baseUrl,
    39→        connectTimeout: const Duration(seconds: 10),
    40→        receiveTimeout: const Duration(seconds: 10),
    41→        contentType: 'application/json',
    42→      ),
    43→    );
    44→
    45→    _initialized = true;
    46→  }
    47→
    48→  /// Hub에 스니펫 업로드
    49→  /// 성공 시 공유 링크 반환
    50→  Future<SnippetUploadResponse> uploadSnippet({
    51→    required String code,
    52→    required String title,
    53→    required List<String> tags,
    54→    String? description,
    55→  }) async {
    56→    try {
    57→      await initialize();
    58→
    59→      final response = await _dio.post<Map<String, dynamic>>(
    60→        '/snippets',
    61→        data: {
    62→          'title': title,
    63→          'code': code,
    64→          'tags': tags,
    65→          'description': description ?? '',
    66→        },
    67→      );
    68→
    69→      if (response.statusCode == 200 || response.statusCode == 201) {
    70→        return SnippetUploadResponse.fromJson(response.data ?? {});
    71→      } else {
    72→        throw Exception('Upload failed: ${response.statusCode}');
    73→      }
    74→    } on DioException catch (e) {
    75→      throw Exception('Upload error: ${e.message}');
    76→    }
    77→  }
    78→
    79→  /// 현재 코드의 추천 태그 생성
    80→  List<String> suggestTags(String code) {
    81→    final tags = <String>{};
    82→
    83→    // 키워드 기반 태그 추천
    84→    if (code.contains('for ') || code.contains('while ')) {
    85→      tags.add('loop');
    86→    }
    87→    if (code.contains('fn ')) {
    88→      tags.add('function');
    89→    }
    90→    if (code.contains('array') || code.contains('[')) {
    91→      tags.add('array');
    92→    }
    93→    if (code.contains('string') || code.contains('"')) {
    94→      tags.add('string');
    95→    }
    96→    if (code.contains('if ') || code.contains('else')) {
    97→      tags.add('conditional');
    98→    }
    99→    if (code.contains('match ')) {
   100→      tags.add('pattern-matching');
   101→    }
   102→    if (code.contains('//')) {
   103→      tags.add('commented');
   104→    }
   105→
   106→    // 코드 길이 기반 태그
   107→    if (code.length < 100) {
   108→      tags.add('snippet');
   109→    } else if (code.length < 500) {
   110→      tags.add('utility');
   111→    } else {
   112→      tags.add('algorithm');
   113→    }
   114→
   115→    return tags.toList();
   116→  }
   117→
   118→  /// 제목 자동 생성 (코드의 첫 줄에서)
   119→  String suggestTitle(String code) {
   120→    final lines = code.split('\n');
   121→    for (final line in lines) {
   122→      final trimmed = line.trim();
   123→      if (trimmed.isNotEmpty && !trimmed.startsWith('//')) {
   124→        // 첫 번째 의미있는 줄에서 제목 추출
   125→        if (trimmed.startsWith('fn ')) {
   126→          final match = RegExp(r'fn\s+(\w+)').firstMatch(trimmed);
   127→          return 'Function: ${match?.group(1) ?? 'unnamed'}';
   128→        }
   129→        return trimmed.length > 50
   130→            ? '${trimmed.substring(0, 47)}...'
   131→            : trimmed;
   132→      }
   133→    }
   134→    return 'Untitled Snippet';
   135→  }
   136→}
