   284→  String _formatTime(DateTime dateTime) {
   285→    final now = DateTime.now();
   286→    final diff = now.difference(dateTime);
   287→
   288→    if (diff.inMinutes < 1) {
   289→      return '방금';
   290→    } else if (diff.inHours < 1) {
   291→      return '${diff.inMinutes}분 전';
   292→    } else if (diff.inDays < 1) {
   293→      return '${diff.inHours}시간 전';
   294→    } else if (diff.inDays < 7) {
   295→      return '${diff.inDays}일 전';
   296→    } else {
   297→      return '${dateTime.year}-${dateTime.month.toString().padLeft(2, '0')}-${dateTime.day.toString().padLeft(2, '0')}';
   298→    }
   299→  }
   300→}
