     1→// autocomplete_popup.dart - 자동 완성 팝업 위젯
     2→
     3→import 'package:flutter/material.dart';
     4→import '../services/lsp_features.dart';
     5→
     6→class AutocompletePopup extends StatefulWidget {
     7→  final String code;
     8→  final int position;
     9→  final Function(String) onSelected;
    10→  final Offset position_offset;
    11→
    12→  const AutocompletePopup({
    13→    Key? key,
    14→    required this.code,
    15→    required this.position,
    16→    required this.onSelected,
    17→    required this.position_offset,
    18→  }) : super(key: key);
    19→
    20→  @override
    21→  State<AutocompletePopup> createState() => _AutocompletePopupState();
    22→}
    23→
    24→class _AutocompletePopupState extends State<AutocompletePopup> {
    25→  late List<CompletionItem> suggestions;
    26→  int selectedIndex = 0;
    27→
    28→  @override
    29→  void initState() {
    30→    super.initState();
    31→    suggestions = AutocompleteProvider.getCompletions(widget.code, widget.position);
    32→  }
    33→
    34→  @override
    35→  Widget build(BuildContext context) {
    36→    if (suggestions.isEmpty) {
    37→      return const SizedBox.shrink();
    38→    }
    39→
    40→    return Positioned(
    41→      left: widget.position_offset.dx,
    42→      top: widget.position_offset.dy,
    43→      child: Material(
    44→        elevation: 8,
    45→        borderRadius: BorderRadius.circular(4),
    46→        child: Container(
    47→          width: 300,
    48→          constraints: const BoxConstraints(maxHeight: 300),
    49→          decoration: BoxDecoration(
    50→            color: Colors.grey[900],
    51→            borderRadius: BorderRadius.circular(4),
    52→            border: Border.all(color: Colors.grey[700]!),
    53→          ),
    54→          child: ListView.builder(
    55→            padding: EdgeInsets.zero,
    56→            itemCount: suggestions.length,
    57→            itemBuilder: (context, index) {
    58→              final item = suggestions[index];
    59→              return CompletionItemWidget(
    60→                item: item,
    61→                isSelected: index == selectedIndex,
    62→                onTap: () => widget.onSelected(item.insertText),
    63→              );
    64→            },
    65→          ),
    66→        ),
    67→      ),
    68→    );
    69→  }
    70→}
    71→
    72→class CompletionItemWidget extends StatelessWidget {
    73→  final CompletionItem item;
    74→  final bool isSelected;
    75→  final VoidCallback onTap;
    76→
    77→  const CompletionItemWidget({
    78→    Key? key,
    79→    required this.item,
    80→    required this.isSelected,
    81→    required this.onTap,
    82→  }) : super(key: key);
    83→
    84→  IconData _getKindIcon(CompletionItemKind kind) {
    85→    switch (kind) {
    86→      case CompletionItemKind.keyword:
    87→        return Icons.label;
    88→      case CompletionItemKind.function:
    89→        return Icons.functions;
    90→      case CompletionItemKind.variable:
    91→        return Icons.checklist;
    92→      case CompletionItemKind.type:
    93→        return Icons.category;
    94→      case CompletionItemKind.module:
    95→        return Icons.library_books;
    96→      case CompletionItemKind.snippet:
    97→        return Icons.code;
    98→    }
    99→  }
   100→
   101→  @override
   102→  Widget build(BuildContext context) {
   103→    return GestureDetector(
   104→      onTap: onTap,
   105→      child: Container(
   106→        color: isSelected ? Colors.teal[700] : Colors.transparent,
   107→        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
   108→        child: Row(
   109→          children: [
   110→            Icon(
   111→              _getKindIcon(item.kind),
   112→              size: 16,
   113→              color: Colors.teal,
   114→            ),
   115→            const SizedBox(width: 8),
   116→            Expanded(
   117→              child: Column(
   118→                crossAxisAlignment: CrossAxisAlignment.start,
   119→                children: [
   120→                  Text(
   121→                    item.label,
   122→                    style: const TextStyle(
   123→                      fontSize: 12,
   124→                      fontWeight: FontWeight.bold,
   125→                      color: Colors.white,
   126→                    ),
   127→                  ),
   128→                  Text(
   129→                    item.detail,
   130→                    style: TextStyle(
   131→                      fontSize: 10,
   132→                      color: Colors.grey[500],
   133→                    ),
   134→                  ),
   135→                ],
   136→              ),
   137→            ),
   138→          ],
   139→        ),
   140→      ),
   141→    );
   142→  }
   143→}
