     1→// lsp_features_test.dart - LSP 기능 테스트
     2→
     3→import 'package:flutter_test/flutter_test.dart';
     4→import 'package:ide/services/lsp_features.dart';
     5→
     6→void main() {
     7→  group('AutocompleteProvider', () {
     8→    test('자동 완성: 키워드 제안', () {
     9→      const code = 'le';
    10→      const position = 2;
    11→
    12→      final completions = AutocompleteProvider.getCompletions(code, position);
    13→
    14→      expect(completions.isNotEmpty, true);
    15→      expect(
    16→        completions.any((item) => item.label == 'let'),
    17→        true,
    18→      );
    19→    });
    20→
    21→    test('자동 완성: 함수 제안', () {
    22→      const code = 'print';
    23→      const position = 5;
    24→
    25→      final completions = AutocompleteProvider.getCompletions(code, position);
    26→
    27→      expect(
    28→        completions.any((item) => item.label == 'print'),
    29→        true,
    30→      );
    31→    });
    32→
    33→    test('자동 완성: 타입 제안', () {
    34→      const code = 'i3';
    35→      const position = 2;
    36→
    37→      final completions = AutocompleteProvider.getCompletions(code, position);
    38→
    39→      expect(
    40→        completions.any((item) => item.label == 'i32'),
    41→        true,
    42→      );
    43→    });
    44→
    45→    test('자동 완성: 스니펫 제안', () {
    46→      const code = 'fn';
    47→      const position = 2;
    48→
    49→      final completions = AutocompleteProvider.getCompletions(code, position);
    50→
    51→      expect(
    52→        completions.any((item) => item.kind == CompletionItemKind.snippet),
    53→        true,
    54→      );
    55→    });
    56→  });
    57→
    58→  group('Linter', () {
    59→    test('린팅: 구문 오류 감지', () {
    60→      const code = 'let x = (1 + 2))';
    61→
    62→      final diagnostics = Linter.lint(code);
    63→
    64→      expect(
    65→        diagnostics.any((d) => d.code == 'syntax-error'),
    66→        true,
    67→      );
    68→    });
    69→
    70→    test('린팅: 미사용 변수 경고', () {
    71→      const code = '''
    72→let unused = 10
    73→let used = 20
    74→print used
    75→''';
    76→
    77→      final diagnostics = Linter.lint(code);
    78→
    79→      expect(
    80→        diagnostics.any((d) => d.code == 'unused-variable'),
    81→        true,
    82→      );
    83→    });
    84→
    85→    test('린팅: 들여쓰기 경고', () {
    86→      const code = 'let x = 1\n   if x { print x }'; // 3칸 들여쓰기
    87→
    88→      final diagnostics = Linter.lint(code);
    89→
    90→      expect(
    91→        diagnostics.any((d) => d.code == 'indentation'),
    92→        true,
    93→      );
    94→    });
    95→
    96→    test('린팅: 명명 컨벤션 경고', () {
    97→      const code = 'let snake_case = 10';
    98→
    99→      final diagnostics = Linter.lint(code);
   100→
   101→      expect(
   102→        diagnostics.any((d) => d.code == 'naming-convention'),
   103→        true,
   104→      );
   105→    });
   106→
   107→    test('린팅: 오류 없음', () {
   108→      const code = '''
   109→let x = 10
   110→let y = 20
   111→print x + y
   112→''';
   113→
   114→      final diagnostics = Linter.lint(code);
   115→
   116→      // 오류 없음 (모두 경고/힌트만 가능)
   117→      expect(
   118→        diagnostics.where((d) => d.severity == DiagnosticSeverity.error).isEmpty,
   119→        true,
   120→      );
   121→    });
   122→  });
   123→
   124→  group('CodeFormatter', () {
   125→    test('포맷팅: 들여쓰기 정규화', () {
   126→      const code = '''fn main() {
   127→    let x = 1
   128→        if x { print x }
   129→}''';
   130→
   131→      final formatted = CodeFormatter.format(code);
   132→
   133→      expect(formatted.contains('  let'), true);
   134→      expect(formatted.contains('    if'), true);
   135→    });
   136→
   137→    test('포맷팅: 공백 정리', () {
   138→      const code = 'let x = 1  \nlet y = 2   ';
   139→
   140→      final formatted = CodeFormatter.format(code);
   141→
   142→      expect(!formatted.contains('  \n'), true);
   143→    });
   144→
   145→    test('포맷팅: 연산자 공백', () {
   146→      const code = 'let x=1+2';
   147→
   148→      final formatted = CodeFormatter.format(code);
   149→
   150→      expect(formatted.contains(' = '), true);
   151→      expect(formatted.contains(' + '), true);
   152→    });
   153→
   154→    test('포맷팅: 파일 끝 개행', () {
   155→      const code = 'let x = 1';
   156→
   157→      final formatted = CodeFormatter.format(code);
   158→
   159→      expect(formatted.endsWith('\n'), true);
   160→    });
   161→
   162→    test('포맷팅: 완전한 코드', () {
   163→      const code = '''fn fib(n) {
   164→if n<=1 { n }
   165→else { fib(n-1)+fib(n-2) }
   166→}''';
   167→
   168→      final formatted = CodeFormatter.format(code);
   169→
   170→      // 정규화되어야 함
   171→      expect(formatted.contains('  if'), true);
   172→      expect(formatted.contains('  else'), true);
   173→      expect(formatted.contains('fn fib'), true);
   174→    });
   175→  });
   176→}
